//! Opening positions for strength tests, generated by our own engine.
//!
//! From the start position, play a few random legal plies, then keep the
//! position if a shallow search finds it roughly balanced, not in check, and
//! not already seen. Everything is seeded, so the same settings produce the
//! same file; the committed `tests/openings/openings.epd` comes from here.

use std::collections::HashSet;
use std::sync::Arc;
use std::sync::atomic::AtomicBool;

use rusty_chess_core::movegen::MoveList;
use rusty_chess_core::position::Position;
use rusty_chess_search::board::Board;
use rusty_chess_search::search::{Limits, Searcher};

/// Generation settings.
#[derive(Clone, Debug)]
pub struct Settings {
    /// How many positions to produce.
    pub count: usize,
    /// Random plies played from the start position.
    pub plies: u32,
    /// The deepest depth of the balancing search.
    pub depth: u32,
    /// Largest absolute score, in centipawns, still considered balanced.
    pub max_cp: i32,
    /// The PRNG seed.
    pub seed: u64,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            count: 300,
            plies: 8,
            depth: 4,
            max_cp: 60,
            seed: 0x0FE4_1A6B_2026_1027,
        }
    }
}

struct Rng(u64);

impl Rng {
    /// Seeded through splitmix64 so that nearby seeds give unrelated streams
    /// and no seed yields the all-zero state xorshift cannot leave.
    fn seeded(seed: u64) -> Rng {
        let mut z = seed.wrapping_add(0x9E37_79B9_7F4A_7C15);
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        Rng((z ^ (z >> 31)) | 1)
    }

    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
}

/// Generate the openings as FEN strings, in generation order.
pub fn generate(settings: &Settings) -> Vec<String> {
    rusty_chess_core::attacks::init();
    let mut rng = Rng::seeded(settings.seed);
    let mut searcher = Searcher::new(Arc::new(AtomicBool::new(false)));
    let limits = Limits {
        depth: Some(settings.depth),
        ..Limits::default()
    };
    let mut seen = HashSet::new();
    let mut out = Vec::with_capacity(settings.count);
    let mut attempts = 0u64;
    while out.len() < settings.count {
        attempts += 1;
        assert!(
            attempts < 1_000_000,
            "could not find enough balanced openings"
        );
        let mut pos = Position::startpos();
        let mut ok = true;
        for _ in 0..settings.plies {
            let mut list = MoveList::new();
            pos.legal_moves(&mut list);
            if list.is_empty() {
                ok = false;
                break;
            }
            let m = list.as_slice()[(rng.next() % list.len() as u64) as usize];
            pos.make_move(m);
        }
        if !ok || pos.in_check() || !seen.insert(pos.key()) {
            continue;
        }
        let mut list = MoveList::new();
        pos.legal_moves(&mut list);
        if list.is_empty() {
            continue;
        }
        let mut board = Board::from_position(pos.clone());
        let result = searcher.search(&mut board, &limits, &mut |_| {});
        if result.score.abs() <= settings.max_cp {
            out.push(pos.to_fen());
        }
    }
    out
}
